use serde::Serialize;

// ── Types ──────────────────────────────────────────────────────────────────────

#[derive(Serialize)]
pub struct GitSyncStatus {
    pub git_available: bool,
    pub repo_initialized: bool,
    pub current_branch: Option<String>,
    pub remote_url: Option<String>,
    pub has_uncommitted_changes: bool,
    pub push_required: bool,
    pub ahead: usize,
    pub behind: usize,
    pub notes_root: String,
}

#[derive(Serialize)]
pub struct GitCommitEntry {
    pub id: String,
    pub short_id: String,
    pub summary: String,
    pub author: String,
    pub authored_ms: Option<i64>,
    pub sync_state: String,
    pub is_head: bool,
}

// ── Trait ──────────────────────────────────────────────────────────────────────

pub trait GitSyncService {
    fn get_status(&self) -> Result<GitSyncStatus, String>;
    fn get_history(&self, limit: Option<usize>) -> Result<Vec<GitCommitEntry>, String>;
    fn connect(
        &self,
        remote_url: &str,
        branch: Option<&str>,
        username: Option<&str>,
        password: Option<&str>,
    ) -> Result<GitSyncStatus, String>;
    fn pull(
        &self,
        branch: Option<&str>,
        username: Option<&str>,
        password: Option<&str>,
    ) -> Result<GitSyncStatus, String>;
    fn push(
        &self,
        message: Option<&str>,
        branch: Option<&str>,
        username: Option<&str>,
        password: Option<&str>,
    ) -> Result<GitSyncStatus, String>;
    fn generate_ssh_key(&self) -> Result<String, String>;
    fn get_ssh_public_key(&self) -> Result<Option<String>, String>;
    fn delete_ssh_key(&self) -> Result<(), String>;
}

/// Internal gateway for libgit2 and SSH-key infrastructure.
pub trait GitSyncGateway {
    type Status;
    type HistoryArgs;
    type History;
    type ConnectArgs;
    type PullArgs;
    type PushArgs;

    fn generate_ssh_key(&self) -> Result<String, String>;
    fn ssh_public_key(&self) -> Result<Option<String>, String>;
    fn delete_ssh_key(&self) -> Result<(), String>;
    fn status(&self) -> Result<Self::Status, String>;
    fn history(&self, args: Option<Self::HistoryArgs>) -> Result<Vec<Self::History>, String>;
    fn connect(&self, args: Self::ConnectArgs) -> Result<Self::Status, String>;
    fn pull(&self, args: Self::PullArgs) -> Result<Self::Status, String>;
    fn push(&self, args: Self::PushArgs) -> Result<Self::Status, String>;
}

// ─── Implementation Notes ─────────────────────────────────────────────────────
//
// GitSyncService provides git-based sync for notes across devices.
// Supports both HTTPS (username/password) and SSH (keypair) authentication.
//
// get_status()
//   in:  nothing
//   out: GitSyncStatus — repo state, branch, remote, uncommitted changes, ahead/behind counts
//   - Returns git_available=true if git2 can open a repo (always true in the Rust impl)
//   - repo_initialized=false if no .git directory exists
//   - push_required=true if there are uncommitted changes, local-only commits, or no upstream
//
// get_history(limit)
//   in:  limit — max number of commits to return, defaults to 40, clamped to 1-200
//   out: Vec<GitCommitEntry> — commit list with sync state
//   - Walks the git log in topological + time order
//   - sync_state is "synced" if the commit is reachable from the upstream, "local" otherwise
//   - is_head marks the current HEAD commit
//
// connect(remote_url, branch, username, password)
//   in:  remote_url — git remote URL (HTTPS or SSH)
//        branch — target branch name, defaults to current branch or "main"
//        username, password — optional HTTPS credentials
//   out: GitSyncStatus — status after connecting
//   - Initializes a git repo if none exists
//   - Sets or updates the "origin" remote URL
//   - Fetches from the remote and fast-forwards if possible
//   - On first sync with an empty local repo, clears bootstrap artifacts so remote content wins;
//     if the device already holds real notes (unborn HEAD), they are committed as
//     "Notes from this device" so the first pull merges both note sets
//   - Uses the app's SSH keypair if available (for SSH URLs)
//
// pull(branch, username, password)
//   in:  branch — target branch, defaults to current
//        username, password — optional HTTPS credentials
//   out: GitSyncStatus — status after pulling
//   - Commits pending local changes first (files are the source of truth;
//     sync never blocks on a dirty tree)
//   - Fetches and performs fast-forward, or three-way merge if needed
//   - On merge conflicts: keeps "ours", saves "theirs" as .conflict files (e.g. note.conflict.md)
//   - Never loses data — conflict files preserve the remote version
//
// push(message, branch, username, password)
//   in:  message — commit message, defaults to "Sync notes"
//        branch — target branch, defaults to current
//        username, password — optional HTTPS credentials
//   out: GitSyncStatus — status after pushing
//   - Stages all changes and commits
//   - Pushes to the remote
//   - Sets upstream tracking on the branch
//   - No-op if push_required is false
//
// generate_ssh_key()
//   in:  nothing
//   out: String — the public key text
//   - Generates an Ed25519 keypair in-process (ssh-key crate, OpenSSH format —
//     no ssh-keygen binary, so it also works on iOS/Android)
//   - Stored in app_data/ssh/{id_ed25519, id_ed25519.pub}
//   - Private key has restricted permissions (0o600 on Unix)
//   - Fails if a key already exists (delete first)
//
// get_ssh_public_key()
//   in:  nothing
//   out: Option<String> — the public key text, or None if no key exists
//
// delete_ssh_key()
//   in:  nothing
//   out: nothing
//   - Removes both private and public key files
//
// Key assumptions for any implementation:
//   - Git repo lives at the notes root directory
//   - Remote is always named "origin"
//   - Authentication: HTTPS (username/password) or SSH (app-managed Ed25519 keypair)
//   - Conflict resolution creates .conflict sibling files instead of losing data
//   - Commit author defaults to "Type Notes Sync <sync@local>"
//   - Timestamps from git history can supplement note front-matter timestamps
use crate::ports::git_sync::GitSyncGateway;

/// Git synchronization application boundary.
pub struct GitSyncUseCases<G> {
    gateway: G,
}

impl<G: GitSyncGateway> GitSyncUseCases<G> {
    pub fn new(gateway: G) -> Self {
        Self { gateway }
    }

    pub fn generate_ssh_key(&self) -> Result<String, String> {
        self.gateway.generate_ssh_key()
    }

    pub fn ssh_public_key(&self) -> Result<Option<String>, String> {
        self.gateway.ssh_public_key()
    }

    pub fn delete_ssh_key(&self) -> Result<(), String> {
        self.gateway.delete_ssh_key()
    }

    pub fn status(&self) -> Result<G::Status, String> {
        self.gateway.status()
    }

    pub fn history(&self, args: Option<G::HistoryArgs>) -> Result<Vec<G::History>, String> {
        self.gateway.history(args)
    }

    pub fn connect(&self, args: G::ConnectArgs) -> Result<G::Status, String> {
        self.gateway.connect(args)
    }

    pub fn pull(&self, args: G::PullArgs) -> Result<G::Status, String> {
        self.gateway.pull(args)
    }

    pub fn push(&self, args: G::PushArgs) -> Result<G::Status, String> {
        self.gateway.push(args)
    }
}
    pub limit: Option<usize>,
}

/// Core Git sync gateway. libgit2 operations, SSH key lookup, and notes
/// root resolution remain in this outer adapter.
pub struct GitSyncAdapter {
    app: AppEnv,
}

impl GitSyncAdapter {
    pub fn new(app: AppEnv) -> Self {
        Self { app }
    }

    fn resolve_settings(&self) -> (PathBuf, crate::ProfileSettings) {
        let root = crate::ensured_notes_root(&self.app).unwrap_or_default();
        let settings = crate::load_profile_settings(&root);
        (root, settings)
    }
}

impl GitSyncGateway for GitSyncAdapter {
    type Status = GitSyncStatus;
    type HistoryArgs = GitHistoryArgs;
    type History = GitCommitHistoryEntry;
    type ConnectArgs = ConnectGitArgs;
    type PullArgs = GitSyncArgs;
    type PushArgs = GitPushArgs;

    fn generate_ssh_key(&self) -> Result<String, String> {
        generate_ssh_keypair(&self.app)
    }

    fn ssh_public_key(&self) -> Result<Option<String>, String> {
        read_ssh_public_key(&self.app)
    }

    fn delete_ssh_key(&self) -> Result<(), String> {
        delete_ssh_keypair(&self.app)
    }

    fn status(&self) -> Result<Self::Status, String> {
        let (root, _) = self.resolve_settings();
        Ok(build_git_status(&root))
    }

    fn history(&self, args: Option<Self::HistoryArgs>) -> Result<Vec<Self::History>, String> {
        let (root, _) = self.resolve_settings();
        let limit = args.and_then(|value| value.limit).unwrap_or(40);
        build_git_history(&root, limit)
    }

    fn connect(&self, args: Self::ConnectArgs) -> Result<Self::Status, String> {
        let (root, settings) = self.resolve_settings();

        let remote_url = args
            .remote_url
            .as_deref()
            .filter(|s| !s.is_empty())
            .unwrap_or(settings.git_remote_url.as_str());
        if remote_url.is_empty() {
            return Err("Remote URL is required.".to_string());
        }

        let branch = args
            .branch
            .as_deref()
            .filter(|s| !s.is_empty())
            .unwrap_or(settings.git_branch.as_str());

        let username = args
            .username
            .as_deref()
            .filter(|s| !s.is_empty())
            .or_else(|| {
                if !settings.git_username.is_empty() {
                    Some(settings.git_username.as_str())
                } else {
                    None
                }
            });

        let password = args
            .password
            .as_deref()
            .filter(|s| !s.is_empty())
            .or_else(|| {
                if !settings.git_password.is_empty() {
                    Some(settings.git_password.as_str())
                } else {
                    None
                }
            });

        let repo = ensure_git_repo(&root)?;
        // Record the remote before anything that can fail, so a half-finished
        // connect (network down, permission prompt pending, …) leaves a state
        // the next pull/push can recover from instead of a repo with no origin.
        ensure_origin_remote(&repo, remote_url)?;
        let target_branch = resolve_target_branch(&repo, Some(branch.to_string()));
        prepare_bootstrap_worktree_for_sync(&root, &repo, &target_branch)?;
        probe_remote_url(remote_url)?;
        switch_or_prepare_branch(&repo, &target_branch)?;
        let ssh_priv = ssh_private_key_if_exists(&self.app);
        let ssh_pub = ssh_public_key_if_exists(&self.app);
        let trusted_host_key = trusted_ssh_host_key_from_settings(&settings);
        let fetched = match perform_fetch(
            &repo,
            &target_branch,
            username,
            password,
            ssh_priv,
            ssh_pub,
            trusted_host_key,
        ) {
            Ok(commit) => Some(commit),
            Err(error) => {
                let lower = error.to_lowercase();
                if lower.contains("couldn't find remote ref") {
                    None
                } else {
                    return Err(error);
                }
            }
        };
        if let Some(fetched_commit) = fetched {
            let analysis = repo
                .merge_analysis(&[&fetched_commit])
                .map_err(map_git_error)?
                .0;
            if analysis.is_fast_forward() || analysis.is_up_to_date() {
                fast_forward_to(&repo, &target_branch, &fetched_commit)?;
            }
        }
        Ok(build_git_status(&root))
    }

    fn pull(&self, args: Self::PullArgs) -> Result<Self::Status, String> {
        let (root, settings) = self.resolve_settings();
        if !git_repo_initialized(&root) {
            return Err("Repository is not initialized. Connect a remote first.".to_string());
        }

        let branch = args
            .branch
            .as_deref()
            .filter(|s| !s.is_empty())
            .unwrap_or(settings.git_branch.as_str());

        let username = args
            .username
            .as_deref()
            .filter(|s| !s.is_empty())
            .or_else(|| {
                if !settings.git_username.is_empty() {
                    Some(settings.git_username.as_str())
                } else {
                    None
                }
            });

        let password = args
            .password
            .as_deref()
            .filter(|s| !s.is_empty())
            .or_else(|| {
                if !settings.git_password.is_empty() {
                    Some(settings.git_password.as_str())
                } else {
                    None
                }
            });

        let repo = open_repo(&root)?;
        let target_branch = resolve_target_branch(&repo, Some(branch.to_string()));
        prepare_bootstrap_worktree_for_sync(&root, &repo, &target_branch)?;
        // Files are the source of truth and merges never block: pending local
        // edits are committed (exactly like push does) instead of failing the
        // pull, so the one-button pull-then-push sync just works.
        if git_has_changes(&repo) {
            let message = if settings.git_commit_message.trim().is_empty() {
                "Sync notes"
            } else {
                settings.git_commit_message.as_str()
            };
            commit_all_changes(&repo, message, &target_branch)?;
        }
        if let Some(remote_url) = git_remote_url(&repo) {
            probe_remote_url(&remote_url)?;
        }
        switch_or_prepare_branch(&repo, &target_branch)?;
        let ssh_priv = ssh_private_key_if_exists(&self.app);
        let ssh_pub = ssh_public_key_if_exists(&self.app);
        let trusted_host_key = trusted_ssh_host_key_from_settings(&settings);
        let fetched = perform_fetch(
            &repo,
            &target_branch,
            username,
            password,
            ssh_priv,
            ssh_pub,
            trusted_host_key,
        )?;
        let (analysis, _) = repo.merge_analysis(&[&fetched]).map_err(map_git_error)?;
        if analysis.is_up_to_date() {
            return Ok(build_git_status(&root));
        }
        if analysis.is_fast_forward() {
            fast_forward_to(&repo, &target_branch, &fetched)?;
            return Ok(build_git_status(&root));
        }
        if analysis.is_normal() {
            merge_fetched_commit(&repo, &target_branch, &fetched)?;
            return Ok(build_git_status(&root));
        }
        Err("Pull failed because local and remote history could not be merged.".to_string())
    }

    fn push(&self, args: Self::PushArgs) -> Result<Self::Status, String> {
        let (root, settings) = self.resolve_settings();
        if !git_repo_initialized(&root) {
            return Err("Repository is not initialized. Connect a remote first.".to_string());
        }

        let branch = args
            .branch
            .as_deref()
            .filter(|s| !s.is_empty())
            .unwrap_or(settings.git_branch.as_str());

        let username = args
            .username
            .as_deref()
            .filter(|s| !s.is_empty())
            .or_else(|| {
                if !settings.git_username.is_empty() {
                    Some(settings.git_username.as_str())
                } else {
                    None
                }
            });

        let password = args
            .password
            .as_deref()
            .filter(|s| !s.is_empty())
            .or_else(|| {
                if !settings.git_password.is_empty() {
                    Some(settings.git_password.as_str())
                } else {
                    None
                }
            });

        let commit_message = args
            .message
            .as_deref()
            .filter(|s| !s.is_empty())
            .unwrap_or(settings.git_commit_message.as_str());

        let repo = open_repo(&root)?;
        let target_branch = resolve_target_branch(&repo, Some(branch.to_string()));
        switch_or_prepare_branch(&repo, &target_branch)?;

        let status_before_push = build_git_status(&root);
        if !status_before_push.push_required {
            return Ok(status_before_push);
        }
        if let Some(remote_url) = git_remote_url(&repo) {
            probe_remote_url(&remote_url)?;
        }
        let _ = commit_all_changes(&repo, commit_message, &target_branch)?;
        let ssh_priv = ssh_private_key_if_exists(&self.app);
        let ssh_pub = ssh_public_key_if_exists(&self.app);
        let trusted_host_key = trusted_ssh_host_key_from_settings(&settings);
        remote_push(
            &repo,
            &target_branch,
            username,
            password,
            ssh_priv,
            ssh_pub,
            trusted_host_key,
        )?;
        Ok(build_git_status(&root))
    }
}

fn remote_push(
    repo: &Repository,
    branch: &str,
    username: Option<&str>,
    password: Option<&str>,
    ssh_private_key: Option<PathBuf>,
    ssh_public_key: Option<PathBuf>,
    trusted_host_key: Option<TrustedSshHostKey>,
) -> Result<(), String> {
    let mut callbacks = build_callbacks(
        username,
        password,
        ssh_private_key.clone(),
            repo.set_head(&local_ref).map_err(map_git_error)?;
            repo.checkout_head(Some(CheckoutBuilder::new().safe()))
                .map_err(map_git_error)?;
            return Ok(());
        }
    }
    repo.set_head(&local_ref).map_err(map_git_error)
}

fn default_signature(repo: &Repository) -> Result<Signature<'_>, String> {
    if let Ok(sig) = repo.signature() {
        return Ok(sig);
    }
    Signature::now("Type Notes Sync", "sync@local").map_err(map_git_error)
}

/// Stage all changes and create a commit on the given branch.
pub fn commit_all_changes(
    repo: &Repository,
    message: &str,
    branch: &str,
) -> Result<Option<Oid>, String> {
    let mut index = repo.index().map_err(map_git_error)?;
    index
        .add_all(["*"].iter(), IndexAddOption::DEFAULT, None)
        .map_err(map_git_error)?;
    index.write().map_err(map_git_error)?;
    if index.is_empty() && !git_has_changes(repo) {
        return Ok(None);
    }
    let tree_id = index.write_tree().map_err(map_git_error)?;
    let tree = repo.find_tree(tree_id).map_err(map_git_error)?;
    let sig = default_signature(repo)?;
    let update_ref = format!("refs/heads/{}", branch);
    let oid = match repo.head() {
        Ok(head) => {
            if let Some(head_oid) = head.target() {
                let parent = repo.find_commit(head_oid).map_err(map_git_error)?;
                repo.commit(Some(&update_ref), &sig, &sig, message, &tree, &[&parent])
                    .map_err(map_git_error)?
            } else {
                repo.commit(Some(&update_ref), &sig, &sig, message, &tree, &[])
                    .map_err(map_git_error)?
            }
        }
        Err(_) => repo
            .commit(Some(&update_ref), &sig, &sig, message, &tree, &[])
            .map_err(map_git_error)?,
    };
    repo.set_head(&update_ref).map_err(map_git_error)?;
    Ok(Some(oid))
}

fn trusted_ssh_host_key_from_settings(
    settings: &crate::ProfileSettings,
) -> Option<TrustedSshHostKey> {
    let host = settings.git_trusted_ssh_host.trim();
    let sha256 = settings.git_trusted_ssh_host_key_sha256.trim();
    if host.is_empty() || sha256.is_empty() {
        return None;
    }
    Some(TrustedSshHostKey {
        host: host.to_string(),
        sha256: sha256.to_string(),
    })
}

fn normalize_ssh_fingerprint(value: &str) -> String {
    value
        .trim()
        .strip_prefix("SHA256:")
        .unwrap_or(value.trim())
        .trim_end_matches('=')
        .to_string()
}

