//! Git operations: repo init, fetch, push, merge, status, history.

use crate::AppEnv;
use base64::{engine::general_purpose::STANDARD_NO_PAD, Engine as _};
use git2::{
    build::CheckoutBuilder, AnnotatedCommit, CertificateCheckStatus, Cred, CredentialType,
    Direction, FetchOptions, IndexAddOption, Oid, PushOptions, RemoteCallbacks, Repository,
    ResetType, Signature, Sort, StatusOptions,
};
use serde::{Deserialize, Serialize};
use std::{
    fs,
    net::{IpAddr, TcpStream, ToSocketAddrs},
    path::{Path, PathBuf},
    time::Duration,
};

use crate::ports::git_sync::GitSyncGateway;
use crate::{is_system_folder_name, ORDER_FILE, PROTECTED_SYSTEM_FOLDERS};

mod ssh_keys;
pub use ssh_keys::{
    delete_ssh_keypair, generate_ssh_keypair, read_ssh_public_key, ssh_private_key_if_exists,
    ssh_public_key_if_exists,
};

// ── Types ──────────────────────────────────────────────────────────────────────

/// Git sync status snapshot returned to the frontend.
#[derive(Serialize)]
pub struct GitSyncStatus {
    pub git_available: bool,
    pub repo_initialized: bool,
    pub current_branch: Option<String>,
    pub remote_url: Option<String>,
    pub has_uncommitted_changes: bool,
    pub push_required: bool,
    pub ahead: usize,
    pub behind: usize,
    pub notes_root: String,
}

/// Single commit entry in the git history list.
#[derive(Serialize)]
pub struct GitCommitHistoryEntry {
    pub id: String,
    pub short_id: String,
    pub summary: String,
    pub author: String,
    pub authored_ms: Option<i64>,
    pub sync_state: String,
    pub is_head: bool,
}

/// Arguments for connecting to a remote git repository.
#[derive(Deserialize)]
pub struct ConnectGitArgs {
    pub remote_url: Option<String>,
    pub branch: Option<String>,
    pub username: Option<String>,
    pub password: Option<String>,
}

/// Arguments for a fetch-merge-push sync cycle.
#[derive(Deserialize)]
pub struct GitSyncArgs {
    pub branch: Option<String>,
    pub username: Option<String>,
    pub password: Option<String>,
}

/// Arguments for committing and pushing local changes.
#[derive(Deserialize)]
pub struct GitPushArgs {
    pub message: Option<String>,
    pub branch: Option<String>,
    pub username: Option<String>,
    pub password: Option<String>,
}

#[derive(Clone)]
pub struct TrustedSshHostKey {
    host: String,
    sha256: String,
}

/// Arguments for fetching commit history.
#[derive(Deserialize)]
pub struct GitHistoryArgs {
    pub limit: Option<usize>,
}

/// Core Git sync gateway. libgit2 operations, SSH key lookup, and notes
/// root resolution remain in this outer adapter.
pub struct GitSyncAdapter {
    app: AppEnv,
}

impl GitSyncAdapter {
    pub fn new(app: AppEnv) -> Self {
        Self { app }
    }

    fn resolve_settings(&self) -> (PathBuf, crate::ProfileSettings) {
        let root = crate::ensured_notes_root(&self.app).unwrap_or_default();
        let settings = crate::load_profile_settings(&root);
        (root, settings)
    }
}

impl GitSyncGateway for GitSyncAdapter {
    type Status = GitSyncStatus;
    type HistoryArgs = GitHistoryArgs;
    type History = GitCommitHistoryEntry;
    type ConnectArgs = ConnectGitArgs;
//! Git sync (libgit2) for the active working folder, mirroring the desktop
//! `commands/git_sync.rs` surface. The SSH-key functions are usable while
//! locked, exactly like the desktop shell.

use type_core::{
    application::git_sync::GitSyncUseCases, ConnectGitArgs, GitHistoryArgs, GitPushArgs,
    GitSyncAdapter, GitSyncArgs,
};

use crate::{current_env, from_json, run_blocking, to_json, unlocked_env, CoreError};

fn git_sync_use_cases() -> Result<GitSyncUseCases<GitSyncAdapter>, String> {
    Ok(GitSyncUseCases::new(GitSyncAdapter::new(unlocked_env()?)))
}

fn git_sync_use_cases_unlocked_not_required() -> Result<GitSyncUseCases<GitSyncAdapter>, String> {
    Ok(GitSyncUseCases::new(GitSyncAdapter::new(current_env()?)))
}

/// Generate the app-managed Ed25519 keypair; returns the public key.
#[uniffi::export(async_runtime = "tokio")]
pub async fn generate_ssh_key() -> Result<String, CoreError> {
    run_blocking(|| git_sync_use_cases_unlocked_not_required()?.generate_ssh_key()).await
}

#[uniffi::export(async_runtime = "tokio")]
pub async fn get_ssh_public_key() -> Result<Option<String>, CoreError> {
    run_blocking(|| git_sync_use_cases_unlocked_not_required()?.ssh_public_key()).await
}

#[uniffi::export(async_runtime = "tokio")]
pub async fn delete_ssh_key() -> Result<(), CoreError> {
    run_blocking(|| git_sync_use_cases_unlocked_not_required()?.delete_ssh_key()).await
}

/// Sync status of the active working folder as JSON (`GitSyncStatus`).
#[uniffi::export(async_runtime = "tokio")]
pub async fn get_git_status() -> Result<String, CoreError> {
    run_blocking(|| to_json(&git_sync_use_cases()?.status()?)).await
}

/// Live transfer progress of the current pull/push as JSON
/// (`GitTransferProgress`; `phase == "idle"` when nothing is in flight).
/// Cheap snapshot read — poll it while a sync action is running.
#[uniffi::export]
pub fn get_git_sync_progress() -> Result<String, CoreError> {
    to_json(&type_core::git_transfer_progress_snapshot()).map_err(CoreError::from)
}

/// `args_json`: optional `GitHistoryArgs`. Returns JSON `Vec<GitCommitHistoryEntry>`.
#[uniffi::export(async_runtime = "tokio")]
pub async fn get_git_history(args_json: Option<String>) -> Result<String, CoreError> {
    run_blocking(move || {
        let args: Option<GitHistoryArgs> = match args_json {
            Some(json) => Some(from_json(&json)?),
            None => None,
        };
        to_json(&git_sync_use_cases()?.history(args)?)
    })
    .await
}

/// `args_json`: `ConnectGitArgs`. Returns JSON `GitSyncStatus`.
#[uniffi::export(async_runtime = "tokio")]
pub async fn connect_git_repo(args_json: String) -> Result<String, CoreError> {
    run_blocking(move || {
        let args: ConnectGitArgs = from_json(&args_json)?;
        to_json(&git_sync_use_cases()?.connect(args)?)
    })
    .await
}

/// `args_json`: `GitSyncArgs`. Returns JSON `GitSyncStatus`.
#[uniffi::export(async_runtime = "tokio")]
pub async fn git_pull(args_json: String) -> Result<String, CoreError> {
    run_blocking(move || {
        let args: GitSyncArgs = from_json(&args_json)?;
        to_json(&git_sync_use_cases()?.pull(args)?)
    })
    .await
}

/// `args_json`: `GitPushArgs`. Returns JSON `GitSyncStatus`.
#[uniffi::export(async_runtime = "tokio")]
pub async fn git_push(args_json: String) -> Result<String, CoreError> {
    run_blocking(move || {
        let args: GitPushArgs = from_json(&args_json)?;
        to_json(&git_sync_use_cases()?.push(args)?)
    })
    .await
}
//! UniFFI bindings over [`type_core`] for non-Tauri shells — React Native via
//! uniffi-bindgen-react-native, or any UniFFI-supported host (Swift/Kotlin).
//!
//! Design:
//! - The Tauri shell speaks JSON over IPC, and this crate mirrors that
//!   contract: structured inputs arrive as JSON strings deserialized into the
//!   same serde arg structs the desktop commands use, and structured outputs
//!   are returned as JSON strings. One set of TypeScript types therefore fits
//!   both shells.
//! - Every exported function is async: core work runs on the Tokio blocking
//!   pool so long git/transcription calls never block the host's JS thread.
//! - [`init_core`] must be called with the app's data directory before any
//!   other function.
//! - Transcription is pluggable: hosts implement [`TranscriptionProvider`]
//!   (a foreign trait) and pass it to `queue_provider_transcriptions` to run
//!   e.g. native on-device speech recognition against pending recordings.

uniffi::setup_scaffolding!();

mod git_sync;
mod handwriting;
mod iroh_sync;
mod notes;
mod profiles;
mod recordings;
mod security;

pub use git_sync::*;
pub use handwriting::*;
pub use iroh_sync::*;
pub use notes::*;
pub use profiles::*;
pub use recordings::*;
pub use security::*;

#[cfg(test)]
mod tests;

use std::sync::RwLock;
use type_core::AppEnv;

// ── Errors ─────────────────────────────────────────────────────────────────────

/// Error surfaced across the FFI boundary. Core reports errors as strings;
/// this wraps them so bindings raise a typed exception with the message.
#[derive(Debug, uniffi::Error)]
#[uniffi(flat_error)]
pub enum CoreError {
    Failure(String),
}

impl std::fmt::Display for CoreError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CoreError::Failure(message) => write!(f, "{message}"),
        }
    }
}

impl std::error::Error for CoreError {}

impl From<String> for CoreError {
    fn from(message: String) -> Self {
        CoreError::Failure(message)
    }
}

// ── App environment ────────────────────────────────────────────────────────────

static APP_ENV: RwLock<Option<AppEnv>> = RwLock::new(None);

/// Initialize the core with the host app's directories. Must be called before
/// any other function. Idempotent — calling it again (e.g. after a React
/// Native reload) replaces the environment.
#[uniffi::export]
pub fn init_core(app_data_dir: String, documents_dir: Option<String>) -> Result<(), CoreError> {
    let mut env = AppEnv::new(app_data_dir);
    if let Some(dir) = documents_dir {
        env = env.with_documents_dir(dir);
    }
    // Mirrors the Tauri shell's setup hook: load persisted security config so
    // the locked/unlocked gate is correct before the first command runs.
    type_core::ensure_security_runtime_initialized_for_setup(&env)?;
    *APP_ENV.write().expect("app env lock poisoned") = Some(env);
    Ok(())
}

/// The environment registered by [`init_core`].
pub(crate) fn current_env() -> Result<AppEnv, String> {
    APP_ENV
        .read()
        .expect("app env lock poisoned")
        .clone()
        .ok_or_else(|| "Core is not initialized — call init_core first.".to_string())
}

/// [`current_env`] plus the same lock gate the desktop commands apply: fails
/// while encrypted mode is locked so note bodies are never served locked.
pub(crate) fn unlocked_env() -> Result<AppEnv, String> {
    let env = current_env()?;
    type_core::ensure_security_unlocked_for_app(&env)?;
    Ok(env)
}

// ── Shared helpers ─────────────────────────────────────────────────────────────

/// Run a blocking core workflow on the Tokio blocking pool.
pub(crate) async fn run_blocking<T, F>(task: F) -> Result<T, CoreError>
where
    T: Send + 'static,
    F: FnOnce() -> Result<T, String> + Send + 'static,
{
    tokio::task::spawn_blocking(task)
        .await
        .map_err(|error| CoreError::Failure(format!("Background task failed: {error}")))?
// The seam between the app and the Rust core.
//
// `RawCore` mirrors the UniFFI exports of crates/type-ffi one-to-one:
// structured inputs/outputs are JSON strings (the same serde shapes the
// desktop Tauri commands speak), and function names are the camelCase form
// uniffi-bindgen-react-native generates from the Rust snake_case exports.
//
// The app never imports the generated turbo module directly. Instead the
// entry point calls `setRawCore(...)` once with either the generated module
// (wired on a Mac — see the package README) or the in-memory mock
// (`mock-core.ts`) when the native library isn't built, e.g. in Expo Go or
// on CI. Everything else goes through `getRawCore()`.

/** Host-implemented transcription backend (FFI foreign trait). */
export interface RawTranscriptionProvider {
  /** Stable identifier used in error messages, e.g. "apple-speech". */
  id(): string;
  /** Transcribe the audio file at `audioPath` (absolute) into plain text. */
  transcribe(audioPath: string): string | Promise<string>;
}

export interface RawCore {
  /** Must be called before anything else. Idempotent across JS reloads. */
  initCore(appDataDir: string, documentsDir: string | undefined): void | Promise<void>;

  // ── Notes ──
  getTree(): Promise<string>;
  readNote(path: string): Promise<string>;
  createNote(argsJson: string): Promise<string>;
  writeNote(path: string, content: string): Promise<void>;
  setNoteTimestamp(argsJson: string): Promise<void>;
  updateNoteMarkers(argsJson: string): Promise<void>;
  getNoteMeta(path: string): Promise<string>;
  listNotePreviews(paths: string[]): Promise<string>;
  moveItems(items: string[], destination: string): Promise<void>;
  deleteItems(items: string[]): Promise<void>;
  renameItem(path: string, newName: string): Promise<string>;
  setOrder(argsJson: string): Promise<void>;

  // ── Working folders ("profiles") + device app config ──
  getProfiles(): Promise<string>;
  createProfile(argsJson: string): Promise<string>;
  setActiveProfile(profileId: string): Promise<string>;
  setProfileNotesRoot(profileId: string, notesRoot: string): Promise<string>;
  updateProfile(argsJson: string): Promise<string>;
  deleteProfile(profileId: string): Promise<string>;
  updateProfileSettings(argsJson: string): Promise<string>;
  updateAppConfig(argsJson: string): Promise<string>;
  createProfilesBackupZip(): Promise<string>;
  exportProfilesToDocuments(): Promise<string>;

  // ── Git sync ──
  generateSshKey(): Promise<string>;
  getSshPublicKey(): Promise<string | undefined>;
  deleteSshKey(): Promise<void>;
  getGitStatus(): Promise<string>;
  getGitHistory(argsJson: string | undefined): Promise<string>;
  connectGitRepo(argsJson: string): Promise<string>;
  gitPull(argsJson: string): Promise<string>;
  gitPush(argsJson: string): Promise<string>;
  startIrohSyncClient(argsJson: string): Promise<string>;
  /** JSON `IrohClientStatus | null` for the Sync screen's connection panel.
   * Optional: absent in native modules generated before it existed. */
  irohClientStatus?(remoteUrl: string): Promise<string>;
  archiveMobileAudioWithIroh(): Promise<string>;
  setMobileAudioGitExclusion(enabled: boolean): Promise<void>;
  /** Snapshot of the in-flight pull/push transfer progress (sync read).
   * Optional: absent in native modules generated before it existed —
   * `core-api` feature-detects and reports idle instead. */
  getGitSyncProgress?(): string;

  // ── Recordings ──
  saveAudioRecording(argsJson: string): Promise<string>;
  queueRecordingTranscriptions(argsJson: string): Promise<string>;
  queueProviderTranscriptions(provider: RawTranscriptionProvider): Promise<string>;
  listRecordings(): Promise<string>;
  readRecordingAudio(path: string): Promise<string>;
  pruneMobileAudioCache(): Promise<string>;

  // ── Photo attachments ──
  saveHandwritingAttachment(argsJson: string): Promise<string>;

  // ── Security ──
  getSecurityState(): Promise<string>;
  enableSecurity(argsJson: string): Promise<string>;
  lockSecurity(): Promise<string>;
  unlockSecurity(argsJson: string): Promise<string>;
  setSecurityPreferences(argsJson: string): Promise<string>;
}

let rawCore: RawCore | null = null;

export const setRawCore = (core: RawCore) => {
  rawCore = core;
};

export const isRawCoreSet = () => rawCore !== null;

export const getRawCore = (): RawCore => {
  if (!rawCore) {
    throw new Error(
      "Rust core is not wired. Call setRawCore(...) at app startup — with the " +
        "generated native module (see packages/mobile-core/README.md) or with " +
        "createMockCore() for demo mode."
    );
  async (): Promise<ProfilesDocumentsExport> =>
    parse(await getRawCore().exportProfilesToDocuments());

// ── Git sync ───────────────────────────────────────────────────────────────────

/** Generate the app-managed Ed25519 keypair; returns the public key. */
export const generateSshKey = (): Promise<string> => getRawCore().generateSshKey();

export const getSshPublicKey = async (): Promise<string | null> =>
  (await getRawCore().getSshPublicKey()) ?? null;

export const deleteSshKey = (): Promise<void> => getRawCore().deleteSshKey();

export const getGitStatus = async (): Promise<GitSyncStatus> =>
  parse(await getRawCore().getGitStatus());

export const getGitHistory = async (
  args?: GitHistoryArgs
): Promise<GitCommitHistoryEntry[]> =>
  parse(
