  );

export const connectGitRepo = async (
  args: ConnectGitArgs
): Promise<GitSyncStatus> =>
  parse(await getRawCore().connectGitRepo(JSON.stringify(args)));

export const gitPull = async (args: GitSyncArgs = {}): Promise<GitSyncStatus> =>
  parse(await getRawCore().gitPull(JSON.stringify(args)));

export const gitPush = async (args: GitPushArgs = {}): Promise<GitSyncStatus> =>
  parse(await getRawCore().gitPush(JSON.stringify(args)));

/** Start/reuse the mobile loopback proxy for an SSH-over-Iroh remote. */
export const startIrohSyncClient = async (
  args: StartIrohClientArgs
): Promise<IrohClientStatus> =>
  parse(await getRawCore().startIrohSyncClient(JSON.stringify(args)));

/**
 * How the direct connection to the computer is doing right now, or null when
 * no proxy has been started this session.
 *
// Committed fallback package entry for clean clones, CI, and Expo Go.
//
// `uniffi-bindgen-react-native` overwrites this file on a Mac with the real
// TurboModule entry during native codegen. Until then, expose the in-memory
// RawCore implementation so TypeScript/Metro can resolve the package root and
// the app can boot in explicitly labelled demo mode.

import { createMockCore } from "./mock-core";

const demoCore = createMockCore({ seed: true });

export const __isDemoCore = true;

export const {
  initCore,
  getTree,
  readNote,
  createNote,
  writeNote,
  setNoteTimestamp,
  updateNoteMarkers,
  getNoteMeta,
  listNotePreviews,
  moveItems,
  deleteItems,
  renameItem,
  setOrder,
  getProfiles,
  createProfile,
  setActiveProfile,
  setProfileNotesRoot,
  updateProfile,
  deleteProfile,
  updateProfileSettings,
  updateAppConfig,
  createProfilesBackupZip,
  exportProfilesToDocuments,
  generateSshKey,
  getSshPublicKey,
  deleteSshKey,
  getGitStatus,
  getGitHistory,
  connectGitRepo,
  gitPull,
  gitPush,
  getGitSyncProgress,
  saveAudioRecording,
  queueRecordingTranscriptions,
  queueProviderTranscriptions,
  listRecordings,
  readRecordingAudio,
