pub fn app_data_dir(app: &AppEnv) -> Result<PathBuf, String> {
    let path = app.app_data_dir.clone();
    if !path.exists() {
        fs::create_dir_all(&path).map_err(|err| err.to_string())?;
    }
    Ok(path)
}

