                extras.push(format!("cleanup_state failed: {value}"));
            }
            if let Some(value) = reset_error {
                extras.push(format!("reset failed: {value}"));
            }
            Err(format!(
                "{error_message} Automatic rollback failed: {}",
                extras.join("; ")
            ))
        }
