        message: Option<&str>,
        branch: Option<&str>,
    ) -> Result<GitSyncStatus, String>;
    fn push(
        &self,
        message: Option<&str>,
        branch: Option<&str>,
        username: Option<&str>,
        password: Option<&str>,
    ) -> Result<GitSyncStatus, String>;
